def rx(k):
    return re.compile(r"\s+".join(re.escape(p) for p in k.split()))
def build(name, pairs):
    t = og_tags.strip((D / f"{name}.html").read_text(encoding="utf-8"))   # the share block is rebuilt in English below
    t = t.replace('<html lang="zh-Hant">', '<html lang="en">')
    t = re.sub(r'(src|poster|href)="(site|studio)/', r'\1="../\2/', t)   # site/ 與 studio/ 只有一份，在 docs/ 底下
    t, k = re.subn(r'href="en/%s\.html" hreflang="en" lang="en">English</a>' % name, 'href="../%s.html" hreflang="zh-Hant" lang="zh-Hant">中文</a>' % name, t)
    assert k == 2, k
    miss = []
    for z, e in sorted(pairs + COMMON, key=lambda p: -len(p[0])):
        t, n = rx(z).subn(lambda m: e, t)
        if n == 0 and (z, e) not in COMMON: miss.append(z[:40])
    t = og_tags.apply(t, name, "en")
    (D / "en" / f"{name}.html").write_text(t, encoding="utf-8")
    left = [(i + 1, l.strip()[:150]) for i, l in enumerate(t.splitlines()) if re.search(r"[　-〿一-鿿＀-￯・]", l)]
    print("==", name, "unmatched keys:", len(miss)); [print("  KEY", m) for m in miss]
    print("   residual lines:", len(left)); [print("  ", n, l) for n, l in left]
for n in og_tags.PAGES: og_tags.write(n, "zh")
for n, p in (("index", INDEX), ("gallery", GALLERY), ("tools", TOOLS), ("studio", STUDIO)): build(n, p)
